insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"the_royal_impostor_q01_fenn_clue","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q01_fenn_start","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q01_painter_witness","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q01_will_witness","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q02_fenn_clue","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q02_garrick_witness","speaker_external_id":"Main Gate Gaurd 2","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q02_tomlin_start","speaker_external_id":"Main Gate Gaurd 1","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q03_fenn_done","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q03_fenn_start","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"he","line_order":0,"content":"יפה! בדקתם שני בעלים שונים ולא הסתמכתם רק על שם החפץ.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"en","line_order":1,"content":"Clue number one: the impostor confuses his and her.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"he","line_order":2,"content":"רמז מספר אחת: המתחזה מתבלבל בין שלו לשלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"he","line_order":3,"content":"עכשיו דברו עם השומרים. מישהו נגע בארוחת הצהריים שלהם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":0,"content":"יש צרה מלכותית: שני אנשים טוענים שהם היועץ האמיתי.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":1,"content":"שניהם אומרים: I am the Royal Advisor!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":2,"content":"שניהם אומרים: אני היועץ המלכותי!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":3,"content":"היועץ האמיתי מכיר את אנשי הממלכה ואת החפצים שלהם. אספו עדויות מוויל ומהציירת.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness","locale":"he","line_order":0,"content":"אני הציירת, והמברשת הזאת שייכת לי.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness","locale":"en","line_order":1,"content":"This is her brush.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness","locale":"he","line_order":2,"content":"זאת המברשת שלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness","locale":"he","line_order":3,"content":"החשוד קרא למברשת שלי שלו. יועץ אמיתי היה מכיר אותי.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_will_witness","locale":"he","line_order":0,"content":"אני ויל הנפח, והפטיש הזה שייך לי.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_will_witness","locale":"en","line_order":1,"content":"This is his hammer.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_will_witness","locale":"he","line_order":2,"content":"זה הפטיש שלו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_will_witness","locale":"he","line_order":3,"content":"מי שמכיר אותי לא יטעה ויאמר שהפטיש שייך לציירת.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"he","line_order":0,"content":"מצוין. הבנתם שהשומרים אומרים our, אבל אנחנו אומרים עליהם their.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"he","line_order":1,"content":"מצוין. הבנתם שהשומרים אומרים \"שלנו\", אבל אנחנו אומרים עליהם \"שלהם\".","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"en","line_order":2,"content":"Clue number two: the impostor claims other people’s things are his.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"he","line_order":3,"content":"רמז מספר שתיים: המתחזה טוען שחפצים של אחרים שייכים לו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"he","line_order":4,"content":"המלך שלח מבחן אחרון. אני אקריא אותו כאן בשער.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":0,"content":"מצאתי רמז ליד העגלה. אני נותן אותו לכם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"en","line_order":1,"content":"This is your clue.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":2,"content":"זה הרמז שלכם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":3,"content":"החשוד החזיק בכריכים ואמר: These are my sandwiches.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":4,"content":"החשוד החזיק בכריכים ואמר: אלה הכריכים שלי.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":5,"content":"המשפט היה תקין, אבל הטענה הייתה שקרית.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":0,"content":"מישהו לקח את ארוחת הצהריים של שנינו, ואני הייתי ער מספיק כדי לראות את זה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"en","line_order":1,"content":"Someone ate our lunch!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":2,"content":"מישהו אכל את ארוחת הצהריים שלנו!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"en","line_order":3,"content":"These are our sandwiches.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":4,"content":"אלה הכריכים שלנו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":5,"content":"כשאתם מדווחים עלינו, נקודת המבט משתנה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":0,"content":"הצלחתם! כל ששת הרמזים התאימו, והמתחזה לא ידע למי שייך דבר.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":1,"content":"הוא הודה שהוא שחקן מהתיאטרון המלכותי שרצה ארוחה חינם בארמון.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":2,"content":"השומרים צעקו: Our lunch?!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":3,"content":"השומרים צעקו: הארוחה שלנו?!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"en","line_order":4,"content":"Questline complete. You exposed the Royal Impostor!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":5,"content":"הקו הושלם. חשפתם את המתחזה המלכותי!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":6,"content":"כל הכבוד! קבלו עכשיו 10 מטבעות.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"he","line_order":0,"content":"המלך אומר שהיועץ האמיתי יודע למי שייך כל דבר בממלכה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"en","line_order":1,"content":"My real advisor knows this kingdom better than anyone.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"he","line_order":2,"content":"היועץ האמיתי שלי מכיר את הממלכה הזאת טוב יותר מכולם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"he","line_order":3,"content":"השלימו את שלושת המשפטים, ואז אמרו שניים מהם בקול כדי למסור את התשובה.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
